package br.com.orientec.backend.adapter.out.persistence.entity.cadastro; import jakarta.persistence.*; import java.time.LocalDate; @Entity @Table(name="pedido") public class Pedido { @Id private Integer id; @Column(name="fornecedor_id") private Integer fornecedorId; private LocalDate dataPedido; private String situacao; private String observacao; private boolean ativo=true; public Pedido(){} public Integer getId(){return id;} public Integer getFornecedorId(){return fornecedorId;} public LocalDate getDataPedido(){return dataPedido;} public String getSituacao(){return situacao;} public String getObservacao(){return observacao;} public boolean isAtivo(){return ativo;} public void setId(Integer v){id=v;} public void setFornecedorId(Integer v){fornecedorId=v;} public void setDataPedido(LocalDate v){dataPedido=v;} public void setSituacao(String v){situacao=v;} public void setObservacao(String v){observacao=v;} public void setAtivo(boolean v){ativo=v;} }
